function updateMetrics(index){if(index<0)return;const spec=C.cells[index],cell=q(`[data-cell="${index}"]`),result=q('.ml-inline-result',cell),metricGrid=q('[data-cell-metrics]',cell),chart=q('[data-cell-chart]',cell),hasMetrics=!!spec.metrics,hasChart=!!spec.visual;if(!hasMetrics&&!hasChart){result.hidden=true;return}result.hidden=false;metricGrid.hidden=!hasMetrics;metricGrid.innerHTML=hasMetrics?Object.entries(spec.metrics).map(([k,v])=>`<div class="ml-metric"><b>${esc(v)}</b><span>${esc(k)}</span></div>`).join(''):'';chart.hidden=!hasChart;if(hasChart){if(C.id==='data_detective'&&index===3)renderFishHistogram(chart);else if(C.id==='data_detective'&&index===4)renderFishBarplot(chart);else if(C.id==='data_detective'&&index===5)renderFishScatter(chart);else if(C.id==='fish_predictor'&&index>=4&&index<=7)renderFishPredictionChart(chart,['linear','tree','forest','neural'][index-4]);else if(C.id==='loan_model_auditor'&&index===1)renderLoanProjectPlots(chart);else if(C.id==='loan_model_auditor'&&index===5)renderLoanRegressorResult(chart);else if(C.id==='loan_model_auditor'&&index===6)renderLoanProjectScore(chart);else if(C.id==='loan_model_auditor'&&index===7)renderLoanModelResult(chart);else if(C.id==='loan_model_auditor'&&index===8)renderLoanAuditResult(chart);else renderMiniChart(index,chart)}}
