function renderMiniChart(seed=0,target){const pts=C.points||[],colors=['#1f7a46','#3977a8','#e7792f','#b44539','#8b6bba','#6c8d43','#b88a27'];target=target||(state.mode==='explore'?q('#exploreChart'):null);if(!target)return;if(C.id==='data_detective'&&seed===3){const bins=[12,34,48,29,18,9,5,3,1];target.innerHTML=`<svg viewBox="0 0 320 220" role="img" aria-label="Histogram of fish weight"><line x1="28" y1="195" x2="310" y2="195" stroke="#91a69b"/>${bins.map((v,i)=>`<rect x="${34+i*30}" y="${190-v*3.2}" width="23" height="${v*3.2}" rx="2" fill="#1f7a46"><title>${v} fish in this weight range</title></rect>`).join('')}<text x="160" y="214" text-anchor="middle" font-size="10" fill="#61716b">Weight ranges</text></svg>`;return}if(C.id==='loan_model_auditor'&&seed===5){target.innerHTML='<div style="display:grid;grid-template-columns:70px 1fr 1fr;gap:6px;text-align:center;font-size:11px"><span></span><strong>Predicted N</strong><strong>Predicted Y</strong><strong>Actual N</strong><div class="ml-metric"><b>18</b><span>correct decline</span></div><div class="ml-metric" style="background:var(--ml-red-soft)"><b>12</b><span>false approval</span></div><strong>Actual Y</strong><div class="ml-metric" style="background:var(--ml-orange-soft)"><b>9</b><span>false denial</span></div><div class="ml-metric"><b>57</b><span>correct approval</span></div></div>';return}target.innerHTML=`<svg viewBox="0 0 320 220" role="img" aria-label="${esc(C.chartLabel)}"><line x1="28" y1="195" x2="310" y2="195" stroke="#91a69b"/><line x1="28" y1="15" x2="28" y2="195" stroke="#91a69b"/>${pts.map((p,i)=>`<circle cx="${28+p[0]*2.65}" cy="${195-p[1]*1.65}" r="${state.mode==='explore'?5:4}" fill="${colors[(p[2]+seed)%colors.length]}" opacity=".82"><title>${esc(p[3]||'data point')}</title></circle>`).join('')}</svg>`}
